# Compare the functions of the package with an independent Python implementation on grids of
# settings. The reference values are in inst/validation/reference/grid_*.csv, generated by
# make_python_grid.py with satrct_reference.py (numpy and scipy). The Python implementation
# finds critical margins, matched levels, break-even sample sizes, sample sizes, optimal
# weights and optimal numbers of concurrent controls numerically, rather than by the closed
# forms used in the package, and computes the score test from numerically maximized
# restricted likelihoods.
#
# For each function and output, the result row reports the largest difference over the grid
# (relative to max(1, |reference|) unless stated) and is a PASS when it does not exceed the
# tolerance.
#
# Run from the package root after devtools::load_all().
# Output: inst/validation/results/validate_python_reference.csv

source("inst/validation/judge.R")
check_loaded()
script <- "validate_python_reference"
ref_dir <- "inst/validation/reference"
read_grid <- function(name) {
  utils::read.csv(file.path(ref_dir, name), stringsAsFactors = FALSE)
}

# Largest difference, treating matching NA and matching infinite values as equal
max_diff <- function(ours, ref, relative = TRUE) {
  special_ours <- is.na(ours) | is.infinite(ours)
  special_ref <- is.na(ref) | is.infinite(ref)
  d <- numeric(length(ref))
  finite <- !special_ours & !special_ref
  d[finite] <- abs(ours[finite] - ref[finite])
  if (relative) {
    d[finite] <- d[finite] / pmax(1, abs(ref[finite]))
  }
  same_special <- special_ours & special_ref & (is.na(ours) == is.na(ref)) &
    (is.na(ours) | ours == ref)
  d[(special_ours | special_ref) & !same_special] <- Inf
  max(d)
}

compare <- function(item, description, grid_name, ours, ref, tol, relative = TRUE) {
  judge(script, item, description, sprintf("%s (%d rows)", grid_name, length(ref)), 0,
        max_diff(ours, ref, relative), "abs", tol = tol,
        note = if (relative) "largest relative difference" else "largest absolute difference")
}

res <- NULL

# ---- mean squared error, break-even bias and sample size ----
g <- read_grid("grid_mse.csv")
res <- rbind(
  res,
  compare("mse_rct", "mse_rct()", "grid_mse.csv",
          mse_rct(g[["n"]], g[["sigma_t"]], g[["sigma_c"]], g[["r"]]), g[["mse_rct"]], 1e-12),
  compare("mse_sat", "mse_sat()", "grid_mse.csv",
          mse_sat(g[["n"]], g[["n_e"]], g[["bias"]], g[["tau"]], g[["sigma_t"]], g[["sigma_c"]]),
          g[["mse_sat"]], 1e-12),
  compare("breakeven_bias", "breakeven_bias(), including NA when the SAT cannot win",
          "grid_mse.csv",
          breakeven_bias(g[["n"]], g[["n_e"]], g[["sigma_t"]], g[["sigma_c"]], g[["r"]]),
          g[["breakeven_bias"]], 1e-10),
  compare("breakeven_n", "breakeven_n() against numerical root finding", "grid_mse.csv",
          breakeven_n(g[["bias"]], g[["n_e"]], g[["tau"]], g[["sigma_t"]], g[["sigma_c"]],
                      g[["r"]]),
          g[["breakeven_n"]], 1e-10)
)

# ---- power and type I error ----
g <- read_grid("grid_power.csv")
for (m in c("z", "t")) {
  s <- g[g[["method"]] == m, ]
  tol <- if (m == "z") 1e-12 else 1e-8
  res <- rbind(
    res,
    compare(paste0("power_rct_", m), sprintf("power_rct(method = \"%s\")", m), "grid_power.csv",
            power_rct(s[["n"]], s[["delta"]], s[["sigma_t"]], s[["sigma_c"]], s[["alpha"]],
                      s[["r"]], method = m),
            s[["power_rct"]], tol, relative = FALSE),
    compare(paste0("power_sat_", m), sprintf("power_sat(method = \"%s\")", m), "grid_power.csv",
            power_sat(s[["n"]], s[["delta"]], s[["n_e"]], s[["bias"]], s[["margin"]], s[["tau"]],
                      s[["sigma_t"]], s[["sigma_c"]], s[["alpha"]], method = m),
            s[["power_sat"]], tol, relative = FALSE)
  )
}

# ---- critical margin and matched significance level ----
g <- read_grid("grid_margin.csv")
ma <- matched_alpha(g[["n"]], g[["delta"]], g[["n_e"]], g[["margin"]], g[["sigma_t"]],
                    g[["sigma_c"]], g[["alpha"]], g[["r"]])
res <- rbind(
  res,
  compare("critical_margin", "critical_margin() against numerical root finding",
          "grid_margin.csv",
          critical_margin(g[["n"]], g[["delta"]], g[["n_e"]], g[["sigma_t"]], g[["sigma_c"]],
                          g[["r"]]),
          g[["critical_margin"]], 1e-10),
  compare("alpha_matched", "matched_alpha(): matched level, relative to the level",
          "grid_margin.csv", ma[["alpha_matched"]] / g[["alpha_matched"]],
          rep(1, nrow(g)), 1e-9),
  compare("matched_power", "matched_alpha(): common power", "grid_margin.csv",
          ma[["power"]], g[["power"]], 1e-12),
  compare("bias_crossing", "matched_alpha(): bias at which the SAT type I error reaches the level",
          "grid_margin.csv", ma[["bias_crossing"]], g[["bias_crossing"]], 1e-9)
)

# ---- sample sizes ----
g <- read_grid("grid_n.csv")
for (m in c("z", "t")) {
  s <- g[g[["method"]] == m, ]
  tol <- if (m == "z") 1e-10 else 1e-7
  res <- rbind(
    res,
    compare(paste0("n_rct_", m), sprintf("n_rct(method = \"%s\")", m), "grid_n.csv",
            n_rct(s[["delta"]], s[["power"]], s[["sigma_t"]], s[["sigma_c"]], s[["alpha"]],
                  s[["r"]], method = m),
            s[["n_rct"]], tol),
    compare(paste0("n_sat_", m), sprintf("n_sat(method = \"%s\"), including Inf", m),
            "grid_n.csv",
            n_sat(s[["delta"]], s[["power"]], s[["n_e"]], s[["bias"]], s[["margin"]],
                  s[["sigma_t"]], s[["sigma_c"]], s[["alpha"]], method = m),
            s[["n_sat"]], tol)
  )
}

# ---- hybrid designs ----
g <- read_grid("grid_hybrid.csv")
hyb <- mse_hybrid(g[["n"]], g[["n_c"]], g[["n_e"]], g[["bias"]], g[["tau"]], g[["sigma_t"]],
                  g[["sigma_c"]])
opt <- optimal_nc(g[["n"]], g[["n_e"]], g[["bias"]], g[["tau"]], g[["sigma_t"]], g[["sigma_c"]])
res <- rbind(
  res,
  compare("mse_hybrid_weight", "mse_hybrid(): optimal weight against numerical minimization",
          "grid_hybrid.csv", hyb[["weight"]], g[["weight"]], 1e-6, relative = FALSE),
  compare("mse_hybrid_mse", "mse_hybrid(): mean squared error at the optimal weight",
          "grid_hybrid.csv", hyb[["mse"]], g[["mse"]], 1e-10),
  compare("optimal_nc_eq6", "optimal_nc() against equation 6 of Pocock (1976)",
          "grid_hybrid.csv", opt[["n_c"]], g[["n_c_opt_eq6"]], 1e-9),
  compare("optimal_nc_numeric", "optimal_nc() against numerical minimization",
          "grid_hybrid.csv", opt[["n_c"]], g[["n_c_opt_numeric"]], 1e-4, relative = FALSE),
  compare("optimal_nc_n_eff", "optimal_nc(): effective number of external controls",
          "grid_hybrid.csv", opt[["n_eff"]], g[["n_eff"]], 1e-10),
  compare("optimal_nc_mse", "optimal_nc(): mean squared error at the optimum",
          "grid_hybrid.csv", opt[["mse"]], g[["mse_opt"]], 1e-9)
)

# ---- exact binary calculations ----
g <- read_grid("grid_sat_binary.csv")
sat <- do.call(rbind, lapply(seq_len(nrow(g)), function(i) {
  oc_sat_binary_exact(g[["n"]][i], g[["p_t"]][i], g[["p0"]][i], g[["margin"]][i],
                      g[["alpha"]][i])
}))
res <- rbind(
  res,
  compare("oc_sat_binary_exact_crit", "oc_sat_binary_exact(): critical value",
          "grid_sat_binary.csv", sat[["crit"]], g[["crit"]], 0, relative = FALSE),
  compare("oc_sat_binary_exact_size", "oc_sat_binary_exact(): size", "grid_sat_binary.csv",
          sat[["size"]], g[["size"]], 1e-12, relative = FALSE),
  compare("oc_sat_binary_exact_prob", "oc_sat_binary_exact(): rejection probability",
          "grid_sat_binary.csv", sat[["prob_reject"]], g[["prob_reject"]], 1e-12,
          relative = FALSE)
)

g <- read_grid("grid_binary.csv")
prob <- vapply(seq_len(nrow(g)), function(i) {
  oc_binary_exact(g[["n_t"]][i], g[["n_c"]][i], g[["p_t"]][i], g[["p_c"]][i], g[["margin"]][i],
                  g[["alpha"]][i], g[["test"]][i], g[["n_ext"]][i], g[["y_ext"]][i])
}, numeric(1))
for (tst in c("score", "pearson", "pearson_cc")) {
  k <- g[["test"]] == tst
  res <- rbind(res, compare(
    paste0("oc_binary_exact_", tst), sprintf("oc_binary_exact(test = \"%s\")", tst),
    "grid_binary.csv", prob[k], g[["prob_reject"]][k], 1e-9, relative = FALSE))
}

# ---- check that the comparison detects a wrong reference value ----
g <- read_grid("grid_power.csv")
s <- g[g[["method"]] == "z", ]
ours <- power_sat(s[["n"]], s[["delta"]], s[["n_e"]], s[["bias"]], s[["margin"]], s[["tau"]],
                  s[["sigma_t"]], s[["sigma_c"]], s[["alpha"]])
wrong <- s[["power_sat"]]
wrong[1] <- wrong[1] + 1e-6
detected <- max_diff(ours, wrong, relative = FALSE) > 1e-12
res <- rbind(res, judge(script, "pipeline_self_check",
                        "One reference power changed by 1e-6 is detected", "grid_power.csv",
                        1, as.numeric(detected), "abs", tol = 0))

finalize_results(res, "inst/validation/results")
